CREATE TABLE discover_reference_options (
    id UUID PRIMARY KEY,
    category VARCHAR(64) NOT NULL,
    code VARCHAR(128) NOT NULL,
    display_name VARCHAR(256) NOT NULL,
    provider_types VARCHAR(256) NOT NULL,
    display_order INTEGER NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT uq_discover_reference_options_category_code UNIQUE (category, code),
    CONSTRAINT ck_discover_reference_options_category CHECK (category IN ('SPECIALITY','SERVICE','FACILITY','LANGUAGE','COUNTRY','STATE','MEDICAL_COUNCIL'))
);

CREATE INDEX ix_discover_reference_options_category_active_order ON discover_reference_options(category, active, display_order, display_name);

